/// Returns the stable operation key for one public opcode.
pub fn operation_key(opcode: u32) -> Option<&'static str> {
    let offset = opcode.checked_sub(OPERATIONS.first()?.0)? as usize;
    OPERATIONS
        .get(offset)
        .filter(|(candidate, _)| *candidate == opcode)
        .map(|(_, key)| *key)
}
